mapper.select:
select record_id, coupon_id, coupon_name, coupon_type, member_id, points_cost, verify_code, status, exchange_time, valid_start_time, valid_end_time, verify_time, verify_merchant_id, verify_by, activity_id, create_by, create_time, update_by, update_time, remark from iip_coupon_record where verify_merchant_id = #{merchantId}
and verify_time >= date_sub(sysdate(), interval #{days} day)
order by verify_time desc, record_id desc
